(function(){
'use strict';
const G=globalThis.UnificationGame,root=document.getElementById('first-term-government'),esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toFixed(1),signed=n=>(n>0?'+':'')+fmt(n),icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
let s=G.restore(window.openai?.widgetState?.privateContent?.game),active='p-rebuild',modal=null,draft=0,lastFocus=null,observer=null,toast='',saving=false;
const groupNames={worker:'노동자',business:'기업인',low:'저소득층',middle:'중산층'};
function face(id,extra=''){const l=G.leaders.find(x=>x.id===id);return `<span class="g-face face-${id} ${extra}" role="img" aria-label="${l.name} 초상" data-face="${id}"></span>`;}
function budgetAmount(i,n){return s.leader==='thatcher'&&[2,5].includes(i)?fmt(G.policies[i].unit*n*.75)+'조':G.amount(i,n);}
function traitSummary(){return {macron:s.turn<=2?'초기 국민 기대 +8':'초기 기대 효과 종료',johnson:'부패 위험 매 턴 +3',mandela:'협상 비용 -1',merkel:'국채 이자 40% 절감',thatcher:'재건과 훈련 예산 25% 절감',kim:'외교 대응 정치력 -1'}[s.leader];}
function campaignPanel(){const l=G.leader(s),r=G.rivalLeader(s),p=s.election||G.polls(s),profile=G.rivalProfiles[r.id],news=s.politicalNews.at(-1);return `<section class="g-campaign" aria-label="대통령과 야당대표의 정치적 경쟁"><div class="g-duel"><button type="button" class="g-contender cursor-interaction" data-open="leader">${face(l.id)}<span><small>대통령 / 당신</small><strong>${l.short}</strong></span></button><button type="button" class="g-race cursor-interaction" data-open="rival"><span class="g-race-label">${s.election?'최종 득표율':'결선 예상 득표율'}</span><span class="g-race-values"><b>${fmt(p.gov)}%</b><span>VS</span><b>${fmt(p.opp)}%</b></span><span class="g-race-track"><span style="width:${p.gov}%"></span></span></button><button type="button" class="g-contender opponent cursor-interaction" data-open="rival"><span><small>야당대표 / 무작위 배정</small><strong>${r.short}</strong></span>${face(r.id)}</button></div><button type="button" class="g-rival-action cursor-interaction" data-open="rival"><span>${icon('swords')} ${profile.role}</span><span>${esc(s.rival.lastAction?s.rival.lastAction.text+' / '+s.rival.lastAction.result:profile.strength)}</span>${icon('chevron-right')}</button></section><button type="button" class="g-pressline cursor-interaction" data-open="media"><b>${icon('newspaper')} 발표 신뢰 ${Math.round(s.mediaTrust)}</b><span>${esc(news?news.headline:'가상 선거 특보: '+r.name+' 야당대표가 통합정부를 견제합니다.')}</span>${icon('chevron-right')}</button>`;}
function rivalBanner(){const r=G.rivalLeader(s),p=G.rivalProfiles[r.id];return `<button type="button" class="g-event-speaker cursor-interaction" data-open="rival">${face(r.id)}<span><small>${s.pending.opening?'이번 임기의 상대 / 무작위 배정':'야당대표'}</small><strong>${r.name}</strong><span>${p.role}</span></span>${icon('chevron-right')}</button>`;}
function eventTrait(o){const l=G.leader(s),c=G.optionCost(s,o);if(c.pp<o.pp)return l.short+' 특성: 정치력 '+(o.pp-c.pp)+' 절감';if(o.cash>0&&c.cash<o.cash)return l.short+' 특성: 외교 지출 40% 절감';if(o.cash<0&&c.cash<o.cash)return l.short+' 특성: 보조금 50% 증가';return '';}
function politicalInfo(type){if(type==='rival'){const l=G.rivalLeader(s),p=G.rivalProfiles[l.id],r=s.rival,poll=G.polls(s);dialog(l.name,p.role,'swords',`<div class="g-rival-profile">${face(l.id,'large')}<div><p class="g-profile-quote">“${p.quote}”</p><small>게임 속 가상 대사</small><p class="g-info">${p.personality}</p></div></div><div class="g-rival-stats">${row('결선 예상 득표율',fmt(poll.opp)+'%')}${row('조직력',Math.round(r.organization)+' / 100')}${row('토론 설득력',p.debate+' / 100')}${row('상대 신뢰',Math.round(r.credibility)+' / 100')}${row('공세의 기세',Math.round(r.momentum)+' / 100')}</div><h3 class="g-section-label">상대의 방식</h3><p class="g-info">${p.strength}</p><h3 class="g-section-label">대응할 여지</h3><p class="g-info">${p.weakness}</p>${r.blockUntil===s.turn?'<p class="g-event-cause">표결 방해 중: 이번 계획 단계의 정책 변경 비용이 1 늘었습니다.</p>':''}${r.lastAction?`<h3 class="g-section-label">최근 공세</h3><p class="g-info">${esc(r.lastAction.text)} ${esc(r.lastAction.result)}</p>`:''}${r.lastResponse?`<h3 class="g-section-label">당신의 대응</h3><p class="g-info">${esc(r.lastResponse)}</p>`:''}`,s.pending?'<button type="button" class="g-apply cursor-interaction" data-open="event">긴급 결정으로 돌아가기</button>':'');return true;}if(type==='media'){dialog('언론과 여론','정부 발표 신뢰 '+Math.round(s.mediaTrust)+' / 100','newspaper',`<p class="g-info">자료 공개와 설명은 발표 신뢰를 높입니다. 대응 회피와 자료 은폐는 신뢰를 낮춥니다. 이 수치는 상대 공세의 효과, 토론 성공 확률과 선거 전망에 반영됩니다.</p><button type="button" class="g-chart-detail" data-progress-pick="mediaTrust">정부 발표 신뢰 변화 그래프</button><div class="g-history">${[...s.politicalNews].reverse().map(n=>`<article><small>${n.turn}턴 / 가상 언론 보도</small><h3>${esc(n.headline)}</h3><p>${esc(n.attack)}</p><small>${esc(n.result)}</small></article>`).join('')||'<article><p>첫 턴 집행부터 언론 보도와 야당의 공세가 기록됩니다.</p></article>'}</div>`);return true;}return false;}

let politicalDraft='brief',politicalInvestment=0;
function presidencyBar(){return councilBar();}
function adviserNote(){const a=G.advice(s)[0];return `<button type="button" class="g-adviser-note cursor-interaction" data-open="advisers">${icon(a.icon)}<span><b>${a.name}</b> ${esc(a.text)}</span></button>`;}
function actionPanel(){const a=G.politicalActions.find(x=>x.id===politicalDraft),p=s.presidency,blocked=G.actionBlocked(s,a.id,politicalInvestment),watch=p.cases.filter(c=>c.status==='watch');dialog('대통령의 정치 행동','이번 턴 1회 / 현재 정치력 '+s.pp,'swords',`<div class="g-action-grid">${G.politicalActions.map(x=>`<button type="button" class="g-action-pick cursor-interaction ${x.id===a.id?'selected':''}" aria-pressed="${x.id===a.id}" data-action-pick="${x.id}"><span>${icon(x.icon)}<b>${x.name}</b><small>${x.covert?'비밀':'공개'} / 정치력 ${x.pp}부터</small></span><p>${x.desc}</p></button>`).join('')}</div>${a.covert?`<div class="g-intrigue-control"><div class="g-control-head"><label for="g-political-investment">추가로 투입할 정치력</label><b data-invest-value>${politicalInvestment}</b></div><input type="range" class="g-slider cursor-interaction" id="g-political-investment" min="0" max="5" step="1" value="${politicalInvestment}"><div class="g-intrigue-odds"><span>다음 ${Math.min(2,G.termLimit(s)-s.turn)}턴 누적 발각 확률</span><b data-discovery>${G.discoveryChance(s,a.id,politicalInvestment)}%</b></div><p class="g-info">정치력을 1 더 쓰면 발각 확률이 5%p 낮아집니다. 인물의 정치 기반도 반영되며 최소 12%의 위험이 남습니다. 발각 시 지지 -8, 발표 신뢰 -12, 의회 협조 -6과 청문회가 발생합니다.</p></div>`:`<p class="g-info g-action-context">${a.id==='investigate'?'확인되지 않은 공세의 출처를 검증합니다. 상대 캠프의 연계가 확인되면 언론 보도에 결과가 남습니다.':a.id==='bargain'?'의회 협조가 오르면 정책 변경 비용이 줄고 탄핵 표결에서도 유리해집니다.':'공개 자료와 설명으로 지지를 회복하고 다음 상대 공세의 영향도 줄입니다.'}</p>`}${watch.length?`<div class="g-watchline">${icon('eye')} 진행 중인 공작 추적 ${watch.length}건 / 다음 턴 발각 판정</div>`:''}<p class="g-fiction">역사적 인물의 실제 행적과 무관한 가상 정치 행동입니다.</p>`,`<span class="g-message" data-action-status role="status">${blocked||'정치력 '+(a.pp+(a.covert?politicalInvestment:0))+' 사용'}</span><button type="button" class="g-apply cursor-interaction" data-political-action ${blocked?'disabled':''}>${a.covert?'비밀 행동 승인':'행동 실행'}</button>`,'political');}
function updatePoliticalDraft(){const a=G.politicalActions.find(x=>x.id===politicalDraft),blocked=G.actionBlocked(s,a.id,politicalInvestment);root.querySelector('[data-invest-value]').textContent=politicalInvestment;root.querySelector('[data-discovery]').textContent=G.discoveryChance(s,a.id,politicalInvestment)+'%';root.querySelector('[data-action-status]').textContent=blocked||'정치력 '+(a.pp+politicalInvestment)+' 사용';root.querySelector('[data-political-action]').disabled=!!blocked;}
function presidencyInfo(type){const p=s.presidency;if(type==='advisers'){showCouncil();return true;}
 if(type==='political'){actionPanel();return true;}
 if(type==='emergency'){const v=G.votes(s),blocked=G.martialBlocked(s),i=p.impeachment;dialog('계엄과 탄핵','대통령 비상권한과 의회의 견제','scale',`<div class="g-constitutional-state"><span>${icon(p.martial.active?'shield-alert':'landmark')} ${p.martial.active?'비상계엄 시행 중':'민간 행정 운영 중'}</span><b>${{none:'직무 수행',motion:'탄핵안 발의',review:'직무 정지',dismissed:'탄핵 절차 종결',removed:'대통령 파면'}[i.stage]}</b></div><h3 class="g-section-label">비상계엄</h3><p class="g-info">계엄은 군을 동원해 비상 통제를 시행하는 선택입니다. 이 게임에서는 거리의 소요와 군 불복종을 즉시 낮추지만, 생활고와 행정 공백 같은 원인은 그대로 남습니다. 선포 뒤에는 의회의 해제 요구와 위법성 심사가 이어집니다.</p><p class="g-info">즉시 소요 -25와 군 불복종 -15. 정치력 5, 국민 지지 -8, 외교 신뢰 -8, 발표 신뢰 -8을 소모합니다. 다음 턴 의회가 해제를 요구합니다.</p>${row('현재 선포 배경',G.martialReason(s))}${row('선포 시 위법성 쟁점',s.risk.military>=75||s.risk.unrest>=75?'+12':'+48 / 비상 기준 미충족')}<div class="g-emergency-actions"><button type="button" class="g-emergency-button cursor-interaction" data-martial ${blocked?'disabled':''}>${p.martial.active?'계엄 시행 중':'비상계엄 선포 / 정치력 5'}</button><button type="button" class="g-inline-power cursor-interaction" data-lift-martial ${!p.martial.active||s.phase==='ended'||i.stage==='review'?'disabled':''}>계엄 해제</button></div>${blocked&&!p.martial.active?`<p class="g-info">${blocked}</p>`:''}<h3 class="g-section-label">탄핵 진행 조건</h3><ol class="g-process"><li><b>발의</b><span>국민 지지 30% 미만 2턴 연속 또는 위법성 증거 60 이상</span></li><li><b>의회 표결</b><span>찬성 67% 이상이면 직무 정지. 정치력 3으로 찬성표 12%p 감소</span></li><li><b>최종 심사</b><span>위법성 증거에서 조사 협조를 뺀 점수 60 이상이면 파면</span></li></ol>${row('국민 지지 / 30% 미만 지속',fmt(v.all)+'% / '+p.lowApprovalTurns+'턴')}${row('예상 탄핵 찬성 / 가결선',G.motionVotes(s)+'% / 67%')}${row('위법성 증거 / 조사 협조',p.evidence+' / '+p.cooperation)}${row('현재 심사 점수 / 파면선',G.courtScore(s)+' / 60')}<p class="g-fiction">가상 통합정부의 게임 규칙입니다. 실제 법적 요건과 절차를 단순화했습니다.</p>`,s.pending?'<button type="button" class="g-apply cursor-interaction" data-open="event">진행 중인 결정으로 돌아가기</button>':'');return true;}return false;}

let selectedAdviser=null;
function adviserFace(id,extra=''){return `<span class="g-adviser-photo adviser-${id} ${extra}" role="img" aria-label="${G.advisers.find(a=>a.id===id).name} 역사 초상"></span>`;}
function adviserStatus(id){const task=s.council.tasks.find(t=>t.adviser===id);return task?G.adviserMissions[id].find(m=>m.id===task.action).place+' 파견 중':(s.council.available[id]||0)>s.turn?'복귀 보고 중':'지시 가능';}
function dossierSetup(){observer?.disconnect();modal=null;const l=G.leaders.find(l=>l.id===s.leader),c=G.scenarios.find(c=>c.id===s.scenario);root.innerHTML=brand('<b>통합정부 구성</b>'+G.termLimit(s)+'턴 / 약 10분')+`<div class="g-dossier-setup"><div class="g-setup-masthead"><span>대통령 취임 준비</span><h2>당신의 첫 번째 임기</h2><p>대통령의 방식과 통일의 출발점을 선택하십시오.</p></div><div class="g-section-number"><b>01</b><h3>대통령</h3><span>선택하지 않은 인물 중 한 명이 정치적 경쟁자가 됩니다</span></div><div class="g-candidate-roster">${G.leaders.map(x=>`<button type="button" data-leader="${x.id}" aria-pressed="${l.id===x.id}" class="g-candidate cursor-interaction ${l.id===x.id?'selected':''}">${face(x.id)}<span class="g-candidate-name">${x.name}</span><small>${x.role}</small></button>`).join('')}</div><section class="g-leader-dossier"><div class="g-dossier-name"><small>대통령 후보 기록</small><h3>${l.name}</h3><p>${l.role}</p><span class="g-seal">${l.power}</span></div><div class="g-dossier-traits"><p><b>강점</b>${l.good}</p><p><b>약점</b>${l.bad}</p><p><b>고유 행동</b>${l.powerText}</p></div><dl class="g-candidate-stats"><div><dt>초기 정치력</dt><dd>${l.pp+(c.id==='war'?4:0)}</dd></div><div><dt>매 턴 정치력</dt><dd>+${l.regen}</dd></div><div><dt>정책 단계 비용</dt><dd>${l.cost}</dd></div><div><dt>초기 의회 협조</dt><dd>${l.assembly}</dd></div></dl></section><div class="g-section-number"><b>02</b><h3>통일 상황</h3><span>취임 첫날의 보고와 위기가 달라집니다</span></div><div class="g-scenario-chooser"><div class="g-scenario-menu">${G.scenarios.map((x,i)=>`<button type="button" class="cursor-interaction ${x.id===c.id?'selected':''}" aria-pressed="${x.id===c.id}" data-scenario="${x.id}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${x.name}</b><small>${x.tag}</small></div>${icon('chevron-right')}</button>`).join('')}</div><section class="g-scenario-file"><div class="g-file-label">취임 전 정세 보고 / 가상 시나리오</div><h3>${c.name}</h3><p>${c.desc}</p><dl><div><dt>인수 부채</dt><dd>${c.debt}조</dd></div><div><dt>행정 집행력</dt><dd>${c.capacity}</dd></div><div><dt>군 통합</dt><dd>${c.army}</dd></div></dl><div class="g-scenario-rule">${icon('file-warning')}<span>${c.rule}</span></div></section></div><footer class="g-setup-footer"><p>역사적 인물의 능력과 통일 이후 사건은 게임을 위한 가상 설정입니다.<br><span>8부처 / 10개 정책 / 10턴 뒤 선거</span></p><button type="button" data-start class="g-next cursor-interaction">취임 선서 ${icon('arrow-right')}</button></footer></div>`;icons();}
function councilBar(){const a=G.advice(s)[0],report=s.council.lastReport?.turn===s.turn?s.council.lastReport:null;return `<section class="g-council-bar" aria-label="대통령 참모진"><div class="g-council-roster">${G.advisers.map(x=>`<button type="button" class="cursor-interaction ${x.id===a.id?'priority':''}" data-adviser="${x.id}">${adviserFace(x.id)}<span><b>${G.adviserProfiles[x.id].short}</b><small>${adviserStatus(x.id)}</small></span></button>`).join('')}</div><div class="g-command-tools"><button type="button" class="cursor-interaction" data-open="political">${icon('swords')}<span>정치 행동<small>${s.presidency.actionTurn===s.turn?'사용 완료':'공개 활동과 비밀 공작'}</small></span></button><button type="button" class="cursor-interaction" data-open="emergency">${icon('scale')}<span>${s.presidency.martial.active?'계엄 시행 중':'계엄과 탄핵'}<small>${s.presidency.evidence>=40?'위법성 증거 '+s.presidency.evidence:'비상권한과 의회'}</small></span></button></div></section><button type="button" class="g-council-message cursor-interaction" data-adviser="${report?report.adviser:a.id}"><b>${s.council.lastReport?.turn===s.turn?'현장 보고':'우선 보고'}</b><span>${esc(s.council.lastReport?.turn===s.turn?s.council.lastReport.text:G.adviserProfiles[a.id].short+': '+a.text)}</span>${icon('chevron-right')}</button>`;}
function showCouncil(id){selectedAdviser=id||selectedAdviser||G.advice(s)[0].id;const a=G.advisers.find(x=>x.id===selectedAdviser),p=G.adviserProfiles[a.id],eventAdvice=s.pending?G.eventAdvice(s):null,advice=eventAdvice?.id===a.id?eventAdvice:G.advice(s).find(x=>x.id===a.id),task=s.council.tasks.find(x=>x.adviser===a.id);dialog('대통령 참모회의','현장 파견과 정무 지시 / 매 턴 1건','users-round',`<div class="g-adviser-roster">${G.advisers.map(x=>`<button type="button" class="cursor-interaction ${x.id===a.id?'selected':''}" aria-pressed="${x.id===a.id}" data-adviser="${x.id}">${adviserFace(x.id)}<b>${G.adviserProfiles[x.id].short}</b><small>${adviserStatus(x.id)}</small></button>`).join('')}</div><div class="g-adviser-dossier"><div class="g-adviser-biography">${adviserFace(a.id,'large')}<small>${a.role}</small><h3>${a.name}</h3><p>${p.line}</p><dl><dt>전문</dt><dd>${p.strength}</dd><dt>대가</dt><dd>${p.weakness}</dd></dl></div><div class="g-adviser-orders">${adviceMarkup(advice)}<button type="button" class="g-order-button g-advice-link cursor-interaction" data-advice-target="${advice.target}">관련 조치 살펴보기 ${icon('arrow-right')}</button>${task?`<p class="g-mission-progress">${icon('clock-3')} ${G.adviserMissions[a.id].find(m=>m.id===task.action).name}<br>다음 턴 집행 때 결과를 보고합니다.</p>`:''}${G.adviserMissions[a.id].map((m,i)=>{const blocked=G.adviserBlocked(s,a.id,m.id);return `<article class="g-mission"><div class="g-mission-title"><span>${String(i+1).padStart(2,'0')}</span><h4>${m.name}</h4></div><p>${m.method}</p><div class="g-mission-effects"><b>${m.effect}</b><span>${m.trade}</span></div><button type="button" class="g-order-button cursor-interaction" data-adviser-action="${m.id}" data-officer="${a.id}" ${blocked?'disabled':''}>${blocked||'임무 지시 / 정치력 '+m.pp} ${!blocked?icon('arrow-right'):''}</button></article>`;}).join('')}<small class="g-order-timing">비용은 지시할 때 지출합니다. 효과는 다음 턴 집행에 반영되고, 완료 후 한 턴 쉬어갑니다.</small></div></div><p class="g-fiction">역사적 인물에서 착안한 가상 참모입니다. 사진과 초상의 출처는 자료실에서 확인할 수 있습니다.</p>`,`<button type="button" class="g-inline-power cursor-interaction" data-open="sources">자료와 초상 출처</button>${s.pending?'<button type="button" class="g-apply cursor-interaction" data-open="event">긴급 보고로 돌아가기</button>':''}`,'council');}
const announcedIncidents=new Set();
function reportEvent(){if(!s.pending)return;const e=G.events[s.pending.id],b=G.regionalEvent(s),officer=({vacuum:'bismarck',autonomy:'bismarck',promise:'keynes',ceasefire:'marshall'})[s.pending.id]||({disease:'nightingale',food:'nightingale',blackout:'marshall',military:'marshall',corruption:'bismarck',credit:'keynes',unrest:'bismarck',politics:'bismarck',media:'bismarck',constitutional:'bismarck',intrigue:'bismarck'})[e.family],a=G.eventAdvice(s),explanation=G.eventExplanation(s),alert=G.eventAlert(s),eventKey=JSON.stringify([s.turn,s.pending.id,s.pending.scene,s.pending.cause]),arrival=!announcedIncidents.has(eventKey),source=b.source?G.regionalSources[b.source]:null;announcedIncidents.add(eventKey);dialog(b.title,b.place+' / '+b.desk,e.family==='opportunity'?'file-check-2':'siren',`<div class="g-event-alert"><span class="g-warning-beacon" aria-hidden="true"></span>${icon(alert.level==='notice'?'file-check-2':'triangle-alert')}<strong>${alert.label}</strong><span>통일 이후 ${s.turn===0?'취임 당일':s.turn+'턴'} / 가상 상황 보고</span></div><p class="g-event-attention" id="g-event-attention">${alert.instruction}</p><div class="g-incident-layout"><div class="g-incident-main">${['politics','media'].includes(e.family)?rivalBanner():''}<div class="g-location-stamp">${icon('map-pin')}<b>${b.place}</b><span>${b.desk}</span></div><p class="g-event-story">${b.body}</p><section class="g-event-explanation"><b>쉽게 말하면</b><p>${explanation.meaning}</p><b>이번에 결정할 것</b><p>${explanation.decision}</p></section>${explanation.terms.length?`<dl class="g-event-terms">${explanation.terms.map(([term,meaning])=>`<div><dt>${esc(term)}</dt><dd>${esc(meaning)}</dd></div>`).join('')}</dl>`:''}<p class="g-event-cause">상황: ${esc(s.pending.cause)}</p><h3 class="g-response-heading">대통령이 결정할 대응안</h3><div class="g-event-choices">${e.options.map((o,i)=>{const blocked=G.optionAllowed(s,o),cost=G.optionCost(s,o);return `<button type="button" class="g-decision cursor-interaction" data-choice="${o.id}" ${blocked?'disabled':''}><span class="g-decision-letter">${String.fromCharCode(65+i)}</span><span class="g-decision-content"><b>${o.title}</b><span class="g-choice-budget">정치력 ${cost.pp}${cost.cash?' / '+(cost.cash>0?'긴급 지출 ':'지원 수입 ')+Math.abs(cost.cash).toFixed(1)+'조':''}</span><small>${esc(G.impactText(s,o))}</small>${blocked?`<em>${blocked}</em>`:eventTrait(o)?`<em>${eventTrait(o)}</em>`:''}</span>${icon('chevron-right')}</button>`;}).join('')}</div>${source?`<p class="g-scene-source">지역 배경 참고: <a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.name}</a></p>`:''}</div><aside class="g-report-adviser">${adviserFace(a.id,'large')}<small>검토 의견 / ${a.role}</small><h3>${a.name}</h3>${adviceMarkup(a)}<button type="button" class="g-order-button cursor-interaction" data-adviser="${a.id}">참모에게 지시 ${icon('arrow-right')}</button></aside></div>`,`<span class="g-message">지역의 산업과 지리를 참고한 통일 이후 가상 사건입니다.</span>${!s.powerUsed?`<button type="button" class="g-inline-power cursor-interaction" data-open="power">${G.leader(s).power}</button>`:''}`,'event',{...alert,arrival});}
function policyAdviser(p){const id=[4,5].includes(p.dept)?'bismarck':p.dept===2?'nightingale':[1,6].includes(p.dept)?'marshall':'keynes';return `<button type="button" class="g-policy-adviser cursor-interaction" data-adviser="${id}">${adviserFace(id)}<span><small>정책 검토 참모</small><b>${G.advisers.find(x=>x.id===id).name}</b><span>${adviserStatus(id)}</span></span>${icon('chevron-right')}</button>`;}
function showSources(){const portraits=[['조지 마셜','https://commons.wikimedia.org/wiki/File:General_George_C._Marshall_(4616939916).jpg','미국 의회도서관 / 알려진 저작권 제한 없음'],['비스마르크','https://commons.wikimedia.org/wiki/File:Franz_von_Lenbach_-_Otto_von_Bismarck_(ca.1890).jpg','프란츠 폰 렌바흐의 초상 / 퍼블릭 도메인'],['케인스','https://commons.wikimedia.org/wiki/File:Keynes_1933.jpg','1933년 사진 / 퍼블릭 도메인'],['나이팅게일','https://commons.wikimedia.org/wiki/File:Florence_Nightingale_by_Henry_Hering,_1858.jpg','헨리 헤링의 사진 / 퍼블릭 도메인']];dialog('자료실','지역 배경과 역사 초상','book-open',`<p class="g-info">지역의 산업, 물류와 생활 기반은 아래 자료를 참고했습니다. 통일 이후 발생한 사건, 대사, 피해와 정책 효과는 모두 게임을 위해 창작했습니다.</p><h3 class="g-section-label">지역 배경</h3><ul class="g-source-list">${Object.values(G.regionalSources).map(x=>`<li><a href="${x.url}" target="_blank" rel="noopener noreferrer">${x.name}</a></li>`).join('')}</ul><h3 class="g-section-label">참모 초상</h3><ul class="g-source-list">${portraits.map(([name,url,credit])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${name}</a><small>${credit}</small></li>`).join('')}</ul><h3 class="g-section-label">글꼴</h3><p class="g-info"><a href="https://github.com/orioncactus/pretendard" target="_blank" rel="noopener noreferrer">Pretendard / SIL Open Font License</a></p><h3 class="g-section-label">인터페이스 참고</h3><p class="g-info"><a href="https://www.positech.co.uk/democracy4/" target="_blank" rel="noopener noreferrer">Positech Games / Democracy 4</a></p>`);}

function democracySetup(){
 observer?.disconnect();modal=null;root.classList.remove('g-in-game');
 const l=G.leaders.find(l=>l.id===s.leader),c=G.scenarios.find(c=>c.id===s.scenario),scenarioIcons={collapse:'building-2',federal:'handshake',gradual:'landmark',war:'shield-alert'};
 root.innerHTML=brand('<b>새 게임</b>10턴 / 약 10분')+`<div class="g-newgame"><div class="g-newgame-title"><h2>대통령을 선택하세요</h2><p>6명의 지도자, 서로 다른 플레이 방식</p></div><div class="g-candidate-roster">${G.leaders.map(x=>`<button type="button" data-leader="${x.id}" aria-pressed="${l.id===x.id}" class="g-candidate cursor-interaction ${l.id===x.id?'selected':''}">${face(x.id)}<span class="g-candidate-caption"><b>${x.short}</b><small>${x.role}</small><span>${l.id===x.id?icon('check'):'정치력 +'+x.regen+' / 턴'}</span></span></button>`).join('')}</div><section class="g-leader-dossier"><div class="g-dossier-name"><h3>${l.name}</h3><p>${l.role}</p></div><div class="g-dossier-traits"><p><b>${icon('plus')} 강점</b>${l.good}</p><p><b>${icon('minus')} 약점</b>${l.bad}</p><p><b>${icon('zap')} 특수 행동</b><span>${l.power}<small>${l.powerText}</small></span></p></div><dl class="g-candidate-stats"><div><dt>시작 정치력</dt><dd>${l.pp+(c.id==='war'?4:0)}</dd></div><div><dt>매 턴 정치력</dt><dd>+${l.regen}</dd></div><div><dt>정책 단계 비용</dt><dd>${l.cost}</dd></div><div><dt>의회 협조</dt><dd>${l.assembly}</dd></div></dl></section><div class="g-newgame-title g-scenario-title"><h2>통일 상황</h2><p>출발 조건과 첫 사건이 달라집니다</p></div><div class="g-scenario-menu">${G.scenarios.map(x=>`<button type="button" class="cursor-interaction ${x.id===c.id?'selected':''}" aria-pressed="${x.id===c.id}" data-scenario="${x.id}">${icon(scenarioIcons[x.id])}<span><b>${x.name}</b><small>${x.tag}</small></span>${x.id===c.id?icon('check'):''}</button>`).join('')}</div><section class="g-scenario-file"><div><h3>${c.name}</h3><p>${c.desc}</p><p class="g-scenario-focus">${G.briefings[c.id].focus}</p><p class="g-scenario-rule">${icon('info')}${c.rule}</p></div><dl><div><dt>시작 부채</dt><dd>${c.debt}<small>조</small></dd></div><div><dt>행정 집행력</dt><dd>${c.capacity}</dd></div><div><dt>군 통합</dt><dd>${c.army}</dd></div></dl></section><footer class="g-setup-footer"><p>선택하지 않은 인물 중 1명이 경쟁자가 됩니다.<br>역사 인물의 능력과 통일 이후 사건은 가상 설정입니다.</p><button type="button" data-start class="g-next cursor-interaction">게임 시작 ${icon('play')}</button></footer></div>`;icons();
}
function democracyRender(){
 if(s.phase==='setup'){setup();return;}observer?.disconnect();modal=null;root.classList.add('g-in-game');
 const l=G.leader(s),r=G.rivalLeader(s),c=G.scenario(s),f=G.finance(s),v=G.votes(s),m=G.metrics(s),poll=s.election||G.polls(s),ended=s.phase==='ended',a=G.advice(s)[0],report=s.council.lastReport?.turn===s.turn?s.council.lastReport:null;
 const ppGain=Math.max(1,l.regen-(s.risk.military>=75?1:0));
 const loc={income:[12,18],corporate:[23,32],rebuild:[40,16],welfare:[67,15],health:[81,28],training:[90,54],admin:[12,76],cohesion:[41,82],security:[62,80],diplomacy:[87,82]};
 const metrics={capacity:[12,52],infra:[40,39],poverty:[66,34],jobs:[76,59],unity:[37,62],army:[57,58]};
 const risks={credit:[25,14],corruption:[25,53],blackout:[53,20],disease:[91,15],food:[74,73],unrest:[51,41],military:[55,91]};
 const departments=[[2,4],[33,3],[70,3],[86,4],[2,89],[32,95],[65,93],[82,94]];
 const metricList=[...G.metricDefs,{id:'health',name:'의료 대응력',unit:'/100'},{id:'foreign',name:'외교 신뢰',unit:'/100'}];metrics.health=[86,40];metrics.foreign=[90,69];
 root.innerHTML=`<header class="g-playhead"><b>첫 번째 임기</b><span>${c.name}</span><small>${ended?'임기 종료':s.turn===0?'취임 당일':s.turn+' / '+G.termLimit(s)+'턴'}</small></header><div class="g-toolbar"><div class="g-finances">${[['세입',f.income],['지출',f.spending],['적자',f.deficit],['부채',s.debt]].map(([name,value],i)=>`<button type="button" class="g-fin cursor-interaction" data-progress-pick="${['income','spending','deficit','debt'][i]}"><span>${name}</span><b>${fmt(value)}<em>조${i===3?'':' / 턴'}</em></b></button>`).join('')}</div><button type="button" class="g-top-capital cursor-interaction" data-open="leader">${icon('zap')}<span><small>정치력</small><b data-pc>${s.pp}</b></span><em>+${ppGain} / 턴</em></button><nav class="g-tools" aria-label="국정 메뉴">${[['progress','chart-line','성과'],['advisers','users-round','참모'],['cabinet','landmark','부처'],['political','swords','정치'],['emergency','scale','계엄'],['history','list','기록'],['tutorial','book-open','안내'],['setup','rotate-ccw','새 게임']].map(([id,ico,label])=>`<button type="button" class="g-tool cursor-interaction" data-open="${id}">${icon(ico)}<span>${label}</span></button>`).join('')}<button type="button" class="g-tool g-advance cursor-interaction ${s.pending?'g-next-urgent':''}" data-next ${ended?'disabled':''} data-tooltip="${s.pending?'긴급 사건 열기':s.turn===G.termLimit(s)-1?'마지막 턴 집행':'다음 턴 집행'}">${icon(s.pending?'siren':'play')}<span>${s.pending?'사건':s.turn===G.termLimit(s)-1?'마지막':'다음'}</span></button></nav></div>${guideBar()}<div class="g-shell"><aside class="g-sidebar"><button type="button" class="g-public cursor-interaction" data-progress-pick="approval" aria-label="국민 지지율 변화 그래프"><span>국민 지지율</span><b data-approval>${fmt(v.all)}%</b><div class="g-track"><span style="width:${v.all}%"></span></div><small>변화 그래프 보기</small></button><h3 class="g-sidebar-heading">유권자 집단</h3><div class="g-groups">${Object.entries(groupNames).map(([id,name])=>`<button type="button" class="g-group cursor-interaction" data-group="${id}">${icon({worker:'hard-hat',business:'briefcase-business',low:'wallet',middle:'users-round'}[id])}<div><div class="g-group-line"><span>${name}</span><b>${Math.round(v.groups[id])}%</b></div><div class="g-track"><span style="width:${v.groups[id]}%"></span></div></div></button>`).join('')}</div><h3 class="g-sidebar-heading">대통령과 경쟁자</h3><div class="g-side-race"><button type="button" data-open="leader" class="cursor-interaction">${face(l.id)}<span><small>대통령</small><b>${l.short}</b><strong>${fmt(poll.gov)}%</strong></span></button><button type="button" data-open="rival" class="cursor-interaction">${face(r.id)}<span><small>야당대표</small><b>${r.short}</b><strong>${fmt(poll.opp)}%</strong></span></button></div><small class="g-race-caption">${s.election?'최종 득표율':'결선 예상 득표율'}</small><button type="button" class="g-side-rival cursor-interaction" data-open="rival">${icon('swords')}<span>${esc(s.rival.lastAction?.text||G.rivalProfiles[r.id].role)}</span>${icon('chevron-right')}</button><button type="button" class="g-side-media cursor-interaction" data-open="media">${icon('newspaper')} 발표 신뢰 <b>${Math.round(s.mediaTrust)}</b></button><p class="g-trait-mini">정책 단계당 정치력 ${G.stepCost(s)}<br>${traitSummary()}</p><button type="button" class="g-power cursor-interaction" data-open="power" ${s.powerUsed||ended?'disabled':''}>${icon('zap')}<span>${s.powerUsed?'특수 행동 사용 완료':l.power}<small>임기 중 1회${l.powerCost?' / 정치력 '+l.powerCost:''}</small></span></button></aside><main class="g-main"><div class="g-mapbar"><strong>정책 지도</strong><span class="g-map-chart-hint">지표를 누르면 변화 그래프</span><div class="g-legend"><span><i class="policy"></i>정책</span><span><i class="metric"></i>지표</span><span><i class="crisis"></i>위기</span></div></div><div class="g-map" aria-label="8부처 정책과 국가 지표, 위기의 영향 관계"><svg class="g-divisions" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M30 0 L31 48 L0 62 M31 48 L30 100 M31 48 L56 100 M31 48 L70 0 M31 48 L100 38 M31 48 L100 73 M31 48 L100 57"/></svg><svg class="g-edges" aria-hidden="true"></svg>${G.ministries.map((name,i)=>`<div class="g-sector" style="left:${departments[i][0]}%;top:${departments[i][1]}%">${name}</div>`).join('')}${G.policies.map((p,i)=>node('p-'+p.id,p.name,'policy',...loc[p.id],icon(p.icon),s.levels[i]===0?'미시행':budgetAmount(i,s.levels[i])+(p.tax?'':' / 턴')+(s.remaining[i]?' / '+s.remaining[i]+'턴':''),p.id==='rebuild'?63:49)).join('')}${metricList.map(q=>node('m-'+q.id,q.name,'metric',...metrics[q.id],`<strong>${q.id==='jobs'?fmt(m[q.id]):Math.round(m[q.id])}</strong><span>${q.unit}</span>`,'',q.id==='infra'?65:51)).join('')}${G.riskDefs.map(q=>node('r-'+q.id,q.name,'crisis',...risks[q.id],`<strong>${Math.round(s.risk[q.id])}</strong><span>${s.risk[q.id]>=75?'위기':s.risk[q.id]>=50?'경보':'감시'}</span>`,'',38)).join('')}</div><div class="g-mapnote">${icon('mouse-pointer-2')}<span data-mapnote></span></div><div class="g-chain-legend"><span class="g-up">녹색 화살표: 수치 증가</span><span class="g-down">주황 화살표: 수치 감소</span></div></main></div><div class="g-livebar ${s.pending?'urgent':''}"><span>${icon(s.pending?'siren':'radio')}<b>${s.pending?'긴급 사건':'최근 보고'}</b></span><button type="button" class="cursor-interaction" data-open="${s.pending?'event':ended?'result':'history'}">${esc(s.pending?G.eventTitle(s):ended?s.outcome:toast||s.history.at(-1)?.title||'정부 출범')} ${icon('chevron-right')}</button></div><section class="g-council-bar" aria-label="참모진"><div class="g-council-roster">${G.advisers.map(x=>`<button type="button" class="cursor-interaction" data-adviser="${x.id}">${adviserFace(x.id)}<span><b>${G.adviserProfiles[x.id].short}</b><small>${adviserStatus(x.id)}</small></span></button>`).join('')}</div><button type="button" class="g-council-message cursor-interaction" data-adviser="${report?report.adviser:a.id}"><span><b>${report?'현장 보고':G.adviserProfiles[a.id].short+'의 조언'}</b>${esc(report?report.text:a.situation+' '+a.recommendation)}</span>${icon('chevron-right')}</button></section><footer class="g-footer"><div class="g-time"><strong>${ended?'임기 종료':s.turn+' / '+G.termLimit(s)+'턴'}</strong><div><div class="g-steps" role="progressbar" aria-label="임기 진행" aria-valuemin="0" aria-valuemax="${G.termLimit(s)}" style="--term-count:${G.termLimit(s)}" aria-valuenow="${s.turn}">${Array.from({length:G.termLimit(s)},(_,i)=>`<span class="${i<s.turn?'done':''}"></span>`).join('')}</div><small>${s.pending?'사건 대응을 선택하세요':ended?'운영 결과를 확인하세요':G.termLimit(s)-s.turn+'턴 뒤 선거'}</small></div></div></footer><div class="g-bottom"><span>${s.changes.length?esc(s.changes.join(', ')):'8부처 / 10개 정책 / 통일 이후 가상 시뮬레이션'}</span><button type="button" class="cursor-interaction" data-open="sources">자료와 초상 출처</button></div><div class="g-layer" hidden></div>`;
 icons();observer=new ResizeObserver(draw);observer.observe(root.querySelector('.g-map'));draw();
}
function democracyPolicy(id){
 const i=G.policies.findIndex(p=>p.id===id),p=G.policies[i];active='p-'+id;draw();draft=s.levels[i];
 dialog(p.name,G.ministries[p.dept],p.icon,`<div class="g-policy-overview"><div><p class="g-description">${p.desc}</p><div class="g-policy-rule">${G.leader(s).short}: 정책 단계당 정치력 ${G.stepCost(s)}<br>${G.scenario(s).rule}</div><div class="g-policy-implementation"><span>효과 반영</span><b>${G.delay(s,i)}턴</b><span>현재 예산</span><b>${budgetAmount(i,s.levels[i])}</b></div></div>${policyAdviser(p)}</div><div class="g-policy-effects">${p.links.map(([key,d])=>`<div><span>${G.names[key]}</span><b class="${d>0?'positive':'negative'}">${d>0?'↑':'↓'}</b><small>예산 확대 시</small></div>`).join('')}</div><div class="g-control"><div class="g-control-head"><label for="g-policy-slider">${p.tax?'세율':'매 턴 사업 예산'}</label><b data-draft>${budgetAmount(i,draft)}</b></div><input id="g-policy-slider" class="g-slider cursor-interaction" type="range" min="0" max="4" step="1" value="${draft}" ${s.phase!=='planning'?'disabled':''}><div class="g-ticks"><span>${p.tax?'0%':'미시행'}</span><span>현재 ${budgetAmount(i,s.levels[i])}</span><span>${budgetAmount(i,4)}</span></div></div><div class="g-preview"><div><span>${p.tax?'세입':'지출'} 변화 / 턴</span><b data-cost-diff>0.0조</b></div><div><span>효과 반영 기간</span><b>${G.delay(s,i)}턴</b></div><div><span>정치력 비용</span><b data-pc-cost>0 / ${s.pp}</b></div></div><p class="g-info">${s.remaining[i]?'현재 변경안은 '+s.remaining[i]+'턴에 걸쳐 반영 중입니다.':'예산은 다음 턴부터 지출됩니다. 정책 효과는 집행 기간에 걸쳐 반영됩니다.'}</p>`,`<span class="g-message" role="status" aria-live="polite">${s.phase==='incident'?'긴급 사건에 먼저 대응하세요.':s.phase==='ended'?'임기가 종료되었습니다.':'슬라이더를 움직여 예산을 조정하세요.'}</span><button type="button" class="g-apply cursor-interaction" data-apply disabled>${icon('check')}변경 적용</button>`,'policy');modal.index=i;
}

function adviceMarkup(a){return `<div class="g-advice-detail"><p><b>상황 판단</b>${esc(a.situation||a.text)}</p>${a.recommendation?`<p><b>지금 할 일</b>${esc(a.recommendation)}</p><p><b>감수할 점</b>${esc(a.tradeoff)}</p>`:''}</div>`;}
function openAdviceTarget(target){if(G.policies.some(p=>p.id===target))policy(target);else showInfo(target);}
function guideBar(){
 if(s.phase==='ended')return '';
 const risk=rankedRisks()[0],a=G.advice(s)[0];
 const ready=s.changes.length>0||s.council.orderedTurn===s.turn||s.presidency.actionTurn===s.turn;
 const text=s.pending?'먼저 현장 보고를 읽고 대응안을 하나 선택하세요. 사건 대응을 마쳐야 정책 예산을 바꿀 수 있습니다.':ready?'결정한 정책은 다음 턴부터 예산이 지출되고 효과가 반영됩니다. 더 바꿀 일이 없다면 상단 다음 버튼을 누르세요.':'긴급 대응을 마쳤습니다. 남은 정치력 '+s.pp+'점으로 정책 예산을 조절하거나 참모에게 임무를 지시하세요. 모든 부처를 한 번에 바꿀 필요는 없습니다.';
 return `<section class="g-guidance" aria-label="지금 할 일"><div><b>${s.pending?'사건 결재':ready?'집행 준비':'정책과 참모 지시'}</b><p>${text}</p><small>가장 높은 위험: ${risk.name} ${Math.round(s.risk[risk.id])} / 남은 집행 ${G.termLimit(s)-s.turn}턴</small></div><button type="button" class="g-order-button cursor-interaction" ${s.pending?'data-open="event"':'data-advice-target="'+a.target+'"'}>${s.pending?'현장 보고 열기':'우선 조치 살펴보기'} ${icon('arrow-right')}</button></section>${G.termLimit(s)===20?'<p class="g-legacy-note">이 저장은 이전 20턴 규칙으로 이어집니다. 새 게임은 10턴으로 진행됩니다.</p>':''}`;
}
function showTutorial(){
 if(s.phase==='setup')return;
 if(!s.tutorial)s.tutorial={step:0,done:false};
 const b=G.briefings[s.scenario],l=G.leader(s),step=s.tutorial.step;
 const pages=[
  {title:'당신은 방금 취임한 대통령입니다',body:`<p class="g-tutorial-lead">${b.story}</p><div class="g-tutorial-focus"><b>이번 임기의 첫 과제</b><p>${b.focus}</p></div><p>${G.termLimit(s)}번의 정책 집행 뒤 선거를 치릅니다. 주민의 생활을 회복하고 정치적 위기를 버텨, 경쟁자보다 높은 득표율을 얻는 것이 목표입니다. 현재 선택한 대통령은 ${l.name}입니다.</p>`},
  {title:'한 턴에는 이 순서로 움직입니다',body:`<ol class="g-tutorial-flow"><li><b>사건에 답하기</b><p>담당 기관의 보고를 읽고 대통령이 승인할 대응안 하나를 고릅니다. 선택에 따른 수치 변화와 긴급 지출은 즉시 적용됩니다. 같은 턴에 다른 사건의 결정이 이어질 수도 있습니다.</p></li><li><b>정책과 참모 지시</b><p>정책의 둥근 아이콘을 눌러 부처 예산을 조절합니다. 참모 파견은 전체 참모를 합쳐 턴당 한 번입니다. 참모 사진을 눌러 구체적인 조언과 임무를 볼 수 있습니다.</p></li><li><b>다음 턴 집행</b><p>상단 ‘다음’을 누르면 세금과 지출이 계산되고, 정책 효과와 참모 임무가 반영됩니다. 새 사건과 상대 진영의 공세도 이어집니다.</p></li></ol>`},
  {title:'정치력과 예산은 서로 다릅니다',body:`<dl class="g-tutorial-resources"><div><dt>정치력 ${s.pp}</dt><dd>대통령이 정책을 바꾸고 사건에 대응할 때 쓰는 행동 점수입니다. ${l.short}은 기본적으로 매 턴 정치력 ${l.regen}점을 얻고, 정책 한 단계 변경에는 현재 ${G.stepCost(s)}가 듭니다. 사건에 쓸 몫도 남겨두세요.</dd></div><div><dt>매 턴 예산</dt><dd>정부는 정책을 유지하는 동안 매 턴 예산을 지출합니다. 세입은 정부가 거두는 돈입니다. 지출이 세입보다 많으면 적자가 생기고, 정부가 부족한 돈을 빌리므로 부채가 늘어납니다.</dd></div><div><dt>효과 반영 시간</dt><dd>정책에 표시된 ‘2턴’은 효과가 두 번의 집행에 걸쳐 반영된다는 뜻입니다. 예산을 올린 순간 모든 문제가 해결되지는 않습니다.</dd></div></dl>`},
  {title:s.pending?'이제 현장 보고를 읽어보세요':'이제 국정을 운영해 보세요',body:`<div class="g-map-reading"><p><b>회색 원은 정책</b>눌러서 담당 부처와 예산을 확인합니다.</p><p><b>파란 원은 국가 지표</b>의료 대응력과 군 통합은 높을수록 좋지만, 빈곤과 실업률은 낮을수록 좋습니다.</p><p><b>주황 원은 위험</b>높을수록 나쁩니다. 위험 수치가 50 이상이면 관련 사건이 발생할 수 있고, 75 이상이면 피해가 큰 사건이 발생할 수 있습니다. 게임은 해당 수치에 도달한 모든 위험에서 매번 사건을 발생시키지는 않습니다.</p></div><p>화살표 색은 좋고 나쁨이 아니라 <b>수치가 늘어나는지 줄어드는지</b>를 뜻합니다. 상단 <b>계엄</b> 메뉴에는 비상계엄과 탄핵 절차가 있습니다. 선포는 큰 대가가 있으니 일반 정책과 함께 비교하세요.</p><p class="g-tutorial-focus">${s.pending?'지금은 <b>'+esc(G.eventTitle(s))+'</b> 보고부터 읽고, 각 결재안 아래의 비용과 결과를 비교하면 됩니다.':'국정 지도의 가장 높은 위험을 확인한 뒤 관련 정책과 참모 임무를 살펴보세요. 결정을 마쳤다면 다음 턴을 집행하면 됩니다.'}</p>`}
 ];
 const page=pages[step];
 dialog(page.title,'처음 플레이 안내 '+(step+1)+' / '+pages.length,'book-open',`<div class="g-tutorial">${page.body}</div>`,`<button type="button" class="g-inline-power cursor-interaction" data-tutorial-skip>안내 건너뛰기</button><div class="g-tutorial-nav">${step?'<button type="button" class="g-inline-power cursor-interaction" data-tutorial-prev>이전</button>':''}<button type="button" class="g-apply cursor-interaction" ${step===pages.length-1?'data-tutorial-finish':'data-tutorial-next'}>${step===pages.length-1?(s.pending?'현장 보고 읽기':'국정 지도로 돌아가기'):'계속'} ${icon('arrow-right')}</button></div>`,'tutorial');
 root.querySelector('[data-close]').setAttribute('aria-label','안내 닫고 현안 보기');
}
function finishTutorial(){s.tutorial.done=true;render();if(s.pending)showEvent();save();}
function restoreView(){render();if(s.phase!=='setup'&&!s.tutorial?.done&&s.phase!=='ended')showTutorial();else if(s.pending)showEvent();else if(s.phase==='ended')showInfo('result');}

function save(){const brief=s.phase==='setup'?{screen:'시작 설정',leader:s.leader,scenario:s.scenario}:{screen:s.phase==='incident'?'긴급 결정':'국정지도',leader:G.leader(s).name,rival:G.rivalLeader(s).name,election:G.polls(s),mediaTrust:s.mediaTrust,presidency:{martial:s.presidency.martial.active,evidence:s.presidency.evidence,impeachment:s.presidency.impeachment.stage,actionUsed:s.presidency.actionTurn===s.turn,activeCases:s.presidency.cases.filter(c=>c.status==='watch').length},scenario:G.scenario(s).name,turn:s.turn,politicalCapital:s.pp,risks:s.risk,currentEvent:s.pending?G.eventTitle(s):null,currentPlace:G.regionalEvent(s)?.place||null,adviserTasks:s.council.tasks,latestChoice:s.history.slice(-1),outcome:s.outcome};saving=true;try{Promise.resolve(window.openai?.setWidgetState?.({modelContent:brief,privateContent:{game:G.snapshot(s)}})).catch(()=>{});}finally{saving=false;}}
const icons=()=>{if(globalThis.lucide)lucide.createIcons({attrs:{width:18,height:18}});};
function brand(sub){return `<header class="g-brandbar"><div class="g-brand"><div class="g-brand-icon">${icon('landmark')}</div><div><h1>첫 번째 임기</h1><small>THE FIRST TERM</small></div></div><div class="g-scenario">${sub}</div></header>`;}
function setup(){democracySetup();}
function node(id,name,kind,x,y,inside,sub='',size=56){return `<button type="button" class="g-node cursor-interaction" data-node="${id}" data-kind="${kind}" style="--x:${x}%;--y:${y}%;--size:${size}px" aria-label="${esc(name+' '+sub+(kind!=='policy'?' 변화 그래프':''))}"><span class="g-orb">${inside}</span><b>${name}</b>${sub?`<small>${sub}</small>`:''}${kind!=='policy'?progressBadge(id.slice(2)):''}</button>`;}
function rankedRisks(){return [...G.riskDefs].sort((a,b)=>s.risk[b.id]-s.risk[a.id]);}
function policyLinks(p){const links=p.links.map(([id,direction])=>({from:'p-'+p.id,to:(G.riskDefs.some(r=>r.id===id)?'r-':'m-')+id,direction}));if(!p.tax)links.push({from:'p-'+p.id,to:'r-credit',direction:1});return links;}
function edgesFor(id){const all=G.policies.flatMap(policyLinks);all.push({from:'m-infra',to:'r-disease',direction:-1},{from:'r-blackout',to:'r-disease',direction:1},{from:'r-food',to:'r-unrest',direction:1},{from:'r-unrest',to:'r-military',direction:1});return all.filter(e=>e.from===id||e.to===id);}
function draw(){const board=root.querySelector('.g-map'),svg=root.querySelector('.g-edges');if(!board||!svg)return;const r=board.getBoundingClientRect(),edges=edgesFor(active),related=new Set([active,...edges.map(e=>e.from),...edges.map(e=>e.to)]);root.querySelectorAll('[data-node]').forEach(el=>{el.classList.toggle('is-active',el.dataset.node===active);el.classList.toggle('is-related',el.dataset.node!==active&&related.has(el.dataset.node));el.classList.toggle('is-dim',!related.has(el.dataset.node));});svg.setAttribute('viewBox',`0 0 ${r.width} ${r.height}`);svg.innerHTML='<defs><marker id="u-arrow-up" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="var(--g-green)"/></marker><marker id="u-arrow-down" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="var(--g-red)"/></marker></defs>';
for(const e of edges){const a=root.querySelector(`[data-node="${e.from}"] .g-orb`),b=root.querySelector(`[data-node="${e.to}"] .g-orb`);if(!a||!b)continue;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect(),ax=ar.x+ar.width/2-r.x,ay=ar.y+ar.height/2-r.y,bx=br.x+br.width/2-r.x,by=br.y+br.height/2-r.y,dx=bx-ax,dy=by-ay,len=Math.hypot(dx,dy);if(len<1)continue;const ux=dx/len,uy=dy/len,sx=ax+ux*(ar.width/2+7),sy=ay+uy*(ar.height/2+7),ex=bx-ux*(br.width/2+7),ey=by-uy*(br.height/2+7),bend=Math.min(24,len*.06);svg.innerHTML+=`<path class="g-edge" d="M${sx},${sy} Q${(sx+ex)/2-uy*bend},${(sy+ey)/2+ux*bend} ${ex},${ey}" stroke="var(--g-${e.direction>0?'green':'red'})" marker-end="url(#u-arrow-${e.direction>0?'up':'down'})"/>`;}
const note=root.querySelector('[data-mapnote]');const p=G.policies.find(p=>'p-'+p.id===active),risk=G.riskDefs.find(r=>'r-'+r.id===active);note.textContent=p?p.name+' 확대: '+p.links.map(([k,d])=>(G.names[k]||k)+(d>0?' ↑':' ↓')).join(', '):risk?G.reason(s,risk.id):'원형 정책을 눌러 예산을 조절하세요. 빨간 원은 가장 시급한 위험입니다.';}
function render(){democracyRender();}
function dialog(title,subtitle,ico,body,foot='',type='info',alert=null){modal={type};const layer=root.querySelector('.g-layer');layer.hidden=false;layer.className='g-layer'+(alert&&alert.level!=='notice'?' g-incident-overlay':'');layer.innerHTML=`<section class="g-dialog ${type==='event'?'g-event-dialog':''} ${alert?'g-event-'+alert.level+(alert.arrival?' g-alert-arrival':''):''}" role="${alert&&alert.level!=='notice'?'alertdialog':'dialog'}" ${alert?'aria-describedby="g-event-attention"':''} aria-modal="true" aria-labelledby="g-dialog-title"><header class="g-dialoghead"><div class="g-dialogtitle"><div class="g-dialogicon">${icon(ico)}</div><div><h2 id="g-dialog-title">${esc(title)}</h2><small>${esc(subtitle)}</small></div></div><button type="button" class="g-close cursor-interaction" data-close aria-label="닫고 국정지도 보기">${icon('x')}</button></header><div class="g-dialogbody">${body}</div>${foot?`<footer class="g-dialogfoot">${foot}</footer>`:''}</section>`;root.style.minHeight='';const d=layer.querySelector('.g-dialog');if(d.offsetHeight+105>root.offsetHeight)root.style.minHeight=(d.offsetHeight+115)+'px';icons();layer.querySelector('[data-close]').focus({preventScroll:true});if(!document.documentElement.hasAttribute('data-visualize-standalone'))d.scrollIntoView({block:'start',behavior:'instant'});let aligned=false;const align=()=>{if(aligned||!d.isConnected)return;aligned=true;window.dispatchEvent(new CustomEvent('first-term-dialog',{detail:{top:Math.max(0,root.getBoundingClientRect().top+window.scrollY+d.offsetTop-16)}}));};requestAnimationFrame(()=>requestAnimationFrame(align));setTimeout(align,120);}
function close(){if(modal?.type==='tutorial'){finishTutorial();return;}modal=null;const layer=root.querySelector('.g-layer');if(layer){layer.hidden=true;layer.innerHTML='';}root.style.minHeight='';if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}
const row=(name,value)=>`<div class="g-data-row"><span>${name}</span><b>${value}</b></div>`;
function policy(id){democracyPolicy(id);}
function updateDraft(){const i=modal.index,p=G.policies[i],cost=G.policyCost(s,i,draft),button=root.querySelector('[data-apply]');root.querySelector('[data-draft]').textContent=budgetAmount(i,draft);root.querySelector('[data-cost-diff]').textContent=signed((draft-s.levels[i])*p.unit*(s.leader==='thatcher'&&[2,5].includes(i)?.75:1))+'조';root.querySelector('[data-pc-cost]').textContent=cost+' / '+s.pp;button.disabled=cost===0||cost>s.pp||s.phase!=='planning';button.textContent=cost>s.pp?'정치력 부족':draft===0?'정책 폐지':'변경 적용';root.querySelector('.g-message').textContent=cost>s.pp?'이 변경에는 정치력이 부족합니다.':cost===0?'현재와 같은 단계입니다.':'즉시 적용 후 다른 정책도 변경할 수 있습니다.';root.querySelectorAll('.g-policy-effects b').forEach((el,j)=>{const up=p.links[j][1]*(draft<s.levels[i]?-1:1)>0;el.textContent=up?'↑':'↓';el.className=up?'positive':'negative';});root.querySelectorAll('.g-policy-effects small').forEach(el=>el.textContent=draft<s.levels[i]?'예산 축소 시':'예산 확대 시');}
function showEvent(){reportEvent();}
function showProgress(id='jobs'){const data=G.progressSeries(s,id);if(!data)return;dialog(data.definition.name+' 변화',data.origin==='new'?'취임 이후 기록으로 보는 국정 성과':'기록을 시작한 시점부터 보는 국정 성과','chart-line',G.progressMarkup(s,id),s.pending?'<button type="button" class="g-apply cursor-interaction" data-open="event">사건 대응으로 돌아가기</button>':'');}
function showRisk(id){showProgress(id);}
function progressBadge(id){const data=G.progressSeries(s,id);if(!data||data.delta===0)return '';return `<small class="g-node-change g-change-${data.status}">${data.origin==='new'?'취임':'기록'} 대비 ${signed(data.delta)}${data.definition.unit==='%'?'%p':'점'}</small>`;}

function showRiskDetail(id){const r=G.riskDefs.find(r=>r.id===id),links=G.policies.filter(p=>p.links.some(x=>x[0]===id));const stages=id==='military'?'위험 85 이상이 2턴 연속이면 쿠데타 시도가 발생합니다.':'위험 50부터 사건 후보가 됩니다. 75 이상이면 심각 단계의 사건이 발생할 수 있습니다.';dialog(r.name+' 위험',Math.round(s.risk[id])+' / 100',r.icon,`<p class="g-event-cause">${G.reason(s,id)}</p><p class="g-info">${stages}</p>${row('지난 턴 변화',s.trend[id]===undefined?'아직 집행 전':signed(s.trend[id]))}<p class="g-info" style="margin-top:14px">${id==='blackout'?'위험 65 이상에서 감염병과 소요 위험도 매 턴 상승합니다.':id==='food'?'위험 65 이상에서 감염병과 소요 위험도 매 턴 상승합니다.':id==='credit'?'위험 75 이상이면 국채 이자에 60% 할증이 붙습니다.':id==='corruption'?'위험 70 이상이면 복구 지연과 의회 협조 악화가 누적됩니다.':id==='disease'?'위험 70 이상이면 세입 손실과 소요 증가가 발생합니다.':id==='unrest'?'위험 75 이상이면 세입 손실과 군 불복종 위험 상승이 발생합니다.':'위험 75 이상이면 매 턴 확보하는 정치력이 1 줄어듭니다.'}</p><h3 class="g-section-label">관련 정책</h3><div class="g-related">${links.map(p=>`<button type="button" class="cursor-interaction" data-policy="${p.id}">${p.name}</button>`).join('')}</div>`);}
function showInfo(type,id){if(type==='progress'){showProgress('jobs');return;}if(type==='metric'||type==='group'){showProgress(id);return;}if(type==='tutorial'){s.tutorial={step:0,done:false};showTutorial();save();return;}if(type==='sources'){showSources();return;}if(presidencyInfo(type)||politicalInfo(type))return;const l=G.leader(s),f=G.finance(s),m=G.metrics(s),v=G.votes(s);if(type==='event'){showEvent();return;}if(type==='risk'){showRisk(id);return;}if(type==='finance'){dialog('국가 재정','현재 정책을 유지할 때의 다음 턴 예상','chart-no-axes-combined',row('예상 세입',fmt(f.income)+'조')+row('위기로 인한 세입 손실',fmt(f.loss)+'조')+row('8부처 사업 예산',fmt(f.programs)+'조')+row('기존 국가 운영비',fmt(f.fixed)+'조')+row('국채 이자',fmt(f.interest)+'조')+row('예상 적자',fmt(f.deficit)+'조')+row('현재 부채',fmt(s.debt)+'조')+`<p class="g-info" style="margin-top:12px">사건의 긴급 지출은 추가 국채로 조달합니다. 메르켈은 이자 부담이 40% 적고, 신용 위험 75 이상에서는 이자가 60% 증가합니다.</p>`);return;}
if(type==='leader'){dialog(l.name,l.role,l.icon,`<p class="g-advantage">${l.good}</p><p class="g-drawback">${l.bad}</p>${row('의회 협조',Math.round(v.assembly)+' / 100')}${row('현재 정책 단계당 정치력',G.stepCost(s))}${row('토론 설득력',G.rivalProfiles[l.id].debate+' / 100')}${row('매 턴 확보 정치력',l.regen+(s.risk.military>=75?' - 군 불복종 1':''))}<p class="g-info" style="margin-top:12px">의회 협조가 취임 때보다 8 이상 높아지면 정책 단계당 비용이 1 줄고, 8 이상 낮아지면 1 늘어납니다.</p><h3 class="g-section-label">${l.power}</h3><p class="g-info">${l.powerText}</p><p class="g-fiction">역사적 인물에서 착안한 가상 능력 설정입니다.</p>`);return;}
if(type==='power'){dialog(l.power,l.short+' 고유 행동 / 임기 중 1회',l.icon,`<p class="g-event-story">${l.powerText}</p>${row('정치력 비용',l.powerCost+' / '+s.pp)}<p class="g-info" style="margin-top:12px">${s.powerUsed?'이미 사용한 고유 행동입니다.':'효과가 즉시 반영됩니다. 긴급 사건 대응 중에도 사용할 수 있습니다.'}</p>`,`<span class="g-message">${s.pp<l.powerCost?'정치력이 부족합니다.':'이 효과에는 표시된 대가가 함께 적용됩니다.'}</span><button type="button" class="g-apply cursor-interaction" data-power ${s.powerUsed||s.outcome||s.pp<l.powerCost||s.presidency.impeachment.stage==='review'?'disabled':''}>고유 행동 사용</button>`);return;}
if(type==='cabinet'){dialog('통합정부 8부처','현실의 모든 부처를 재현하지 않고 핵심 역할을 압축했습니다.','users-round',`<div class="g-cabinet">${G.ministries.map((name,i)=>`<section><h3>${name}</h3><p>${G.policies.filter(p=>p.dept===i).map(p=>p.name).join(', ')}</p><div class="g-related">${G.policies.filter(p=>p.dept===i).map(p=>`<button type="button" class="cursor-interaction" data-policy="${p.id}">정책 조정</button>`).join('')}</div></section>`).join('')}</div>`);return;}
if(type==='history'){const last=s.reports.at(-1);dialog('국정 기록','정책 집행과 사건 대응의 결과','newspaper',`${last?`<div class="g-report-summary">${s.turn}턴 집행: 지지 ${signed(last.approval)}%p, 실업률 ${signed(last.jobs)}%p, 재정 적자 ${fmt(last.deficit)}조, 정치력 +${last.political}</div>`:''}<div class="g-history">${[...s.history].reverse().map(h=>`<article><small>${h.turn===0?'취임 당일':h.turn+'턴'} / ${h.type==='power'?'고유 행동':['political-action','covert'].includes(h.type)?'정치 행동':h.type==='martial'?'계엄':h.type==='scandal'?'게이트':'사건 대응'}</small><h3>${esc(h.title)}</h3><p>${esc(h.choice)}</p><small>${esc(h.result)}</small></article>`).join('')||'<p class="g-info">아직 결정한 사건이 없습니다.</p>'}</div>`);return;}
if(type==='group'){dialog(groupNames[id],Math.round(v.groups[id])+'% 지지','users-round',`<p class="g-info">${{south:'실업과 소득세 부담, 전반적인 위기 대응을 평가합니다.',north:'빈곤 완화와 지역 신뢰, 전반적인 위기 대응을 평가합니다.',worker:'고용 개선에 특히 민감합니다.',business:'법인세 부담과 고용 여건에 반응합니다.',low:'생계 지원으로 인한 빈곤 완화에 민감합니다.',middle:'소득세와 일자리 문제에 민감합니다.'}[id]}</p>${row('전체 국민 지지',fmt(v.all)+'%')}<p class="g-info" style="margin-top:12px">동일 주민이 지역, 직업과 소득 집단에 동시에 속합니다. 전체 지지는 지역별 인구 비중을 반영하며, 위 집단 지지율의 단순 평균과 다릅니다.</p>`);return;}
if(type==='metric'){const related=G.policies.filter(p=>p.links.some(([k])=>k===id));dialog(G.names[id],(id==='jobs'?fmt(m[id])+'%':Math.round(m[id])+' / 100'),'activity',`<p class="g-info">정책 효과는 예산을 바꾼 즉시 완성되지 않고 시행 기간에 걸쳐 반영됩니다. 사건의 선택도 이 지표를 바꿉니다.</p><div class="g-related">${related.map(p=>`<button type="button" class="cursor-interaction" data-policy="${p.id}">${p.name}</button>`).join('')}</div>`);return;}
if(type==='result'){dialog(s.outcome||'임기 평가',l.short+' / '+G.scenario(s).name,'flag',`<div class="g-report-title">${s.election?'최종 득표':'현재 예상 득표'} ${fmt((s.election||G.polls(s)).gov)}%</div>${row(G.rivalLeader(s).short+' 득표율',fmt((s.election||G.polls(s)).opp)+'%')}${row('국정 지지',fmt(v.all)+'%')}${row('완료한 턴',s.turn+' / '+G.termLimit(s))}${row('대응한 사건',s.history.filter(h=>h.type!=='power').length+'건')}${row('국가 부채',fmt(s.debt)+'조')}${row('지역 신뢰',Math.round(m.unity)+' / 100')}${row('남은 심각한 위험',rankedRisks().filter(r=>s.risk[r.id]>=75).map(r=>r.name).join(', ')||'없음')}<p class="g-info" style="margin-top:12px">${s.election?'국정 지지와 상대 후보의 조직력, 신뢰, 공세를 함께 반영한 결선 득표율이 50% 이상이면 재선합니다.':s.presidency.impeachment.stage==='removed'?'탄핵 심사에서 중대한 위법성이 인정되어 임기가 종료됐습니다.':'위기로 인해 선거 전에 임기가 끝났습니다.'}</p>`,`<button type="button" class="g-inline-power cursor-interaction" data-open="history">선택 기록 보기</button><button type="button" class="g-apply cursor-interaction" data-restart>다른 대통령으로 시작</button>`);return;}
if(type==='setup'){dialog('새 임기 시작','현재 플레이를 끝내고 선택 화면으로 돌아갑니다.','rotate-ccw','<p class="g-info">대통령과 통일 시나리오를 다시 고를 수 있습니다. 현재 진행은 초기화되고, 야당대표도 새로 무작위 배정됩니다.</p>','<button type="button" class="g-apply cursor-interaction" data-restart>새 임기 시작</button>');}}
root.addEventListener('pointerover',e=>{const point=e.target.closest('[data-progress-point]');if(point){G.inspectProgress(root,s,point.dataset.progressPoint);return;}const el=e.target.closest('[data-node]');if(el&&!modal&&el.dataset.node!==active){active=el.dataset.node;draw();}});
root.addEventListener('focusin',e=>{const el=e.target.closest('[data-node]');if(el&&!modal){active=el.dataset.node;draw();}});
root.addEventListener('input',e=>{if(e.target.hasAttribute('data-progress-scrub')){G.inspectProgress(root,s,e.target.value);return;}if(e.target.id==='g-political-investment'){politicalInvestment=Number(e.target.value);updatePoliticalDraft();return;}if(e.target.id==='g-policy-slider'&&modal?.type==='policy'){draft=Number(e.target.value);updateDraft();}});
root.addEventListener('click',e=>{const point=e.target.closest('[data-progress-point]');if(point){G.inspectProgress(root,s,point.dataset.progressPoint);return;}const b=e.target.closest('button');if(!b){if(e.target.classList.contains('g-layer'))close();return;}if(b.disabled)return;if(b.hasAttribute('data-progress-pick')){lastFocus=b;showProgress(b.dataset.progressPick);return;}if(b.hasAttribute('data-risk-detail')){showRiskDetail(b.dataset.riskDetail);return;}if(b.hasAttribute('data-leader')){s.leader=b.dataset.leader;setup();save();return;}if(b.hasAttribute('data-scenario')){s.scenario=b.dataset.scenario;setup();save();return;}if(b.hasAttribute('data-start')){announcedIncidents.clear();s=G.start(s.leader,s.scenario);restoreView();save();return;}if(b.hasAttribute('data-close')){close();return;}if(b.hasAttribute('data-restart')){announcedIncidents.clear();s=G.initial();root.style.minHeight='';toast='';setup();save();return;}
if(b.hasAttribute('data-tutorial-next')){s.tutorial.step=Math.min(3,s.tutorial.step+1);showTutorial();save();return;}
if(b.hasAttribute('data-tutorial-prev')){s.tutorial.step=Math.max(0,s.tutorial.step-1);showTutorial();save();return;}
if(b.hasAttribute('data-tutorial-finish')||b.hasAttribute('data-tutorial-skip')){finishTutorial();return;}
if(b.hasAttribute('data-advice-target')){openAdviceTarget(b.dataset.adviceTarget);return;}
if(b.hasAttribute('data-adviser')){lastFocus=b;showCouncil(b.dataset.adviser);return;}
if(b.hasAttribute('data-adviser-action')){const id=b.dataset.officer;if(G.dispatchAdviser(s,id,b.dataset.adviserAction)){render();save();showCouncil(id);}return;}
if(b.hasAttribute('data-action-pick')){politicalDraft=b.dataset.actionPick;actionPanel();return;}
if(b.hasAttribute('data-political-action')){if(G.politicalAction(s,politicalDraft,politicalInvestment)){toast=s.history.at(-1).title+' / '+s.history.at(-1).result;render();save();}return;}
if(b.hasAttribute('data-martial')){if(G.declareMartial(s)){toast='비상계엄 선포 / 다음 턴 의회의 해제 심사';render();save();showInfo('emergency');}return;}
if(b.hasAttribute('data-lift-martial')){if(G.liftMartial(s)){toast='계엄 해제, 민간 행정으로 복귀';render();save();if(s.pending)showEvent();}return;}
if(b.hasAttribute('data-choice')){if(G.resolve(s,b.dataset.choice)){toast=s.history.at(-1).choice;render();save();if(s.phase==='ended')showInfo('result');else if(s.pending)showEvent();}return;}
if(b.hasAttribute('data-power')){if(G.usePower(s)){toast=G.leader(s).power+' 사용: '+G.leader(s).powerText;render();save();if(s.pending)showEvent();}return;}
if(b.hasAttribute('data-apply')&&modal?.type==='policy'){const i=modal.index;if(G.applyPolicy(s,i,draft)){toast=G.policies[i].name+' 변경 / '+G.leader(s).short+' 정책 비용 적용';render();save();root.querySelector(`[data-node="p-${G.policies[i].id}"]`).focus({preventScroll:true});}return;}
if(b.hasAttribute('data-next')){if(s.pending){showEvent();return;}if(G.advance(s)){render();showEvent();save();}return;}
lastFocus=b;
if(b.hasAttribute('data-open')){showInfo(b.dataset.open);return;}if(b.hasAttribute('data-policy')){policy(b.dataset.policy);return;}if(b.hasAttribute('data-risk')){showRisk(b.dataset.risk);return;}if(b.hasAttribute('data-group')){showInfo('group',b.dataset.group);return;}
if(b.hasAttribute('data-node')){const id=b.dataset.node.slice(2);if(b.dataset.kind==='policy')policy(id);else showInfo(b.dataset.kind==='crisis'?'risk':'metric',id);}
});
root.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const controls=[...root.querySelectorAll('.g-dialog button:not(:disabled),.g-dialog input:not(:disabled),.g-dialog a[href]')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('openai:set_globals',e=>{if(saving)return;const game=e.detail?.globals?.widgetState?.privateContent?.game;if([4,5,6].includes(game?.version)){s=G.restore(game);restoreView();}});
restoreView();
})();



